<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Connection, Delete, Refresh, Setting, Warning } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiErrorMessage, ensureCsrf } from '../services/api'
import { authStore } from '../stores/auth'
import type { AutoReplyAttempt, AutoReplyAttemptStatus, AutoReplyPolicy, BrowserDevice, BrowserUnreadObservation } from '../types'

type RuntimeState = 'RUNNING'|'REVIEW'|'PAUSED'|'OFFLINE'|'DISABLED'|'ERROR'
const policies=ref<AutoReplyPolicy[]>([]),attempts=ref<AutoReplyAttempt[]>([]),devices=ref<BrowserDevice[]>([]),observations=ref<BrowserUnreadObservation[]>([])
const loading=ref(true),saving=ref(false),awayActionId=ref(''),errorMessage=ref(''),dialogOpen=ref(false),editing=ref<AutoReplyPolicy>()
const activeTab=ref('accounts'),attemptStatusFilter=ref(''),attemptAccountFilter=ref('')
const canManage=computed(()=>authStore.state.user?.role!=='RECRUITER')
const form=reactive({enabled:false,awayMode:'TEMPORARY',awayEndsAt:'',autoSendEnabled:false,responseTimeoutMinutes:120,dailyLimit:20,minimumIntervalSeconds:180,sendingWindowStart:'09:00:00',sendingWindowEnd:'21:00:00',timezone:'Asia/Shanghai',maxConsecutiveFailures:3,replyTemplate:''})
const statusLabels:Record<AutoReplyAttemptStatus,string>={CLAIMED:'处理中',PENDING_REVIEW:'待人工审核',SENT:'已发送',FAILED:'失败',SKIPPED:'已跳过'}
const runtimeMeta:Record<RuntimeState,{label:string,type:'success'|'warning'|'danger'|'info'}>={RUNNING:{label:'自动运行中',type:'success'},REVIEW:{label:'等待人工审核',type:'warning'},PAUSED:{label:'安全暂停',type:'danger'},OFFLINE:{label:'设备未在线',type:'danger'},DISABLED:{label:'策略未启用',type:'info'},ERROR:{label:'账号能力异常',type:'danger'}}
function activeDevice(id:string){return devices.value.find(x=>x.accountId===id&&x.status==='ACTIVE')}
function accountReady(x:AutoReplyPolicy){return x.accountStatus==='ACTIVE'&&x.messageSendCapable}
function runtimeState(x:AutoReplyPolicy):RuntimeState{if(!x.awayActive)return'DISABLED';if(!accountReady(x))return'ERROR';if(x.pausedUntil&&new Date(x.pausedUntil)>new Date())return'PAUSED';const d=activeDevice(x.accountId);if(!d||['OFFLINE','DISABLED'].includes(d.runtimeState))return'OFFLINE';if(d.runtimeState==='PAUSED')return'PAUSED';return x.autoSendEnabled?'RUNNING':'REVIEW'}
const runtimeAccounts=computed(()=>policies.value.map(policy=>({policy,state:runtimeState(policy),device:activeDevice(policy.accountId)})))
const attentionAccounts=computed(()=>runtimeAccounts.value.filter(x=>['PAUSED','OFFLINE','ERROR'].includes(x.state)))
const stats=computed(()=>({total:policies.value.length,running:runtimeAccounts.value.filter(x=>x.state==='RUNNING').length,attention:attentionAccounts.value.length,sentToday:policies.value.reduce((n,x)=>n+x.sentToday,0),online:devices.value.filter(x=>x.status==='ACTIVE'&&x.runtimeState==='RUNNING').length}))
const uncertainDrafts=computed(()=>observations.value.filter(x=>x.fillStatus==='UNKNOWN').length)
function deviceNeedsAttention(x:BrowserDevice){return x.runtimeState==='OFFLINE'||(x.runtimeState==='PAUSED'&&!/^只监测模式|草稿辅助已开启/.test(x.stopReason||''))}
const runtimeWarning=computed(()=>{const stopped=devices.value.filter(x=>x.status==='ACTIVE'&&deviceNeedsAttention(x)).length;if(!stopped&&!uncertainDrafts.value)return'';return`${stopped?`${stopped} 个招聘账号的浏览器任务已安全停止`:''}${stopped&&uncertainDrafts.value?'；':''}${uncertainDrafts.value?`${uncertainDrafts.value} 条草稿填写结果不确定，系统不会自动重试`:''}`})
const filteredAttempts=computed(()=>attempts.value.filter(x=>(!attemptStatusFilter.value||x.status===attemptStatusFilter.value)&&(!attemptAccountFilter.value||x.accountId===attemptAccountFilter.value)))
async function load(){loading.value=true;errorMessage.value='';try{const [p,a,d,o]=await Promise.all([api.get<AutoReplyPolicy[]>('/auto-replies/policies'),api.get<AutoReplyAttempt[]>('/auto-replies/attempts'),api.get<BrowserDevice[]>('/browser-devices'),api.get<BrowserUnreadObservation[]>('/browser-observations')]);policies.value=p.data;attempts.value=a.data;devices.value=d.data;observations.value=o.data}catch(e){errorMessage.value=apiErrorMessage(e,'自动跟进配置加载失败')}finally{loading.value=false}}
function observationAge(x:BrowserUnreadObservation){return Math.max(0,Math.floor((Date.now()-Date.parse(x.firstSeenAt))/60000))}
const eligibilityLabel:Record<BrowserUnreadObservation['eligibilityStatus'],string>={OBSERVING:'等待超时',AWAY_INACTIVE:'托管未开启',DETAIL_REQUIRED:'需复核会话',READY_FOR_REVIEW:'待人工确认',HR_REPLIED:'HR 已回复',HR_HANDLED:'已处理',APPROVED_DRAFT:'草稿已批准',REJECTED:'已拒绝',HUMAN_TAKEOVER:'人工接管'}
async function reviewObservation(x:BrowserUnreadObservation,decision:'APPROVED'|'REJECTED'|'HUMAN_TAKEOVER'){try{let content=x.draftContent||'',note='';if(decision==='APPROVED'){const result=await ElMessageBox.prompt('可在确认前修改草稿。确认后仍不会自动发送。','批准安全草稿',{inputValue:content,inputType:'textarea',confirmButtonText:'批准草稿',cancelButtonText:'取消',inputValidator:v=>String(v).trim().length>0||'草稿不能为空'});content=result.value}else{const result=await ElMessageBox.prompt(decision==='REJECTED'?'请填写拒绝原因':'请填写人工接管备注','处理未读会话',{confirmButtonText:'确认',cancelButtonText:'取消'});note=result.value}await ensureCsrf();await api.put(`/browser-observations/${x.id}/review`,{decision,content:decision==='APPROVED'?content:null,note});ElMessage.success(decision==='APPROVED'?'草稿已批准，仍保持不发送':decision==='REJECTED'?'已拒绝草稿':'已标记人工接管');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'处理失败'))}}
function duration(minutes:number){return minutes<60?`${minutes} 分钟`:`${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`}
function openPolicy(x:AutoReplyPolicy){editing.value=x;Object.assign(form,{enabled:x.enabled,awayMode:x.awayMode==='IN_OFFICE'?'TEMPORARY':x.awayMode,awayEndsAt:x.awayEndsAt||new Date(Date.now()+2*3600000).toISOString(),autoSendEnabled:x.autoSendEnabled,responseTimeoutMinutes:x.responseTimeoutMinutes,dailyLimit:x.dailyLimit,minimumIntervalSeconds:x.minimumIntervalSeconds,sendingWindowStart:x.sendingWindowStart,sendingWindowEnd:x.sendingWindowEnd,timezone:x.timezone,maxConsecutiveFailures:x.maxConsecutiveFailures,replyTemplate:x.replyTemplate});dialogOpen.value=true}
async function save(){if(!editing.value)return;if(form.autoSendEnabled&&!form.enabled){ElMessage.error('开启自动发送前必须启用托管');return}saving.value=true;try{await ensureCsrf();const payload={...form,awayMode:form.enabled?form.awayMode:'IN_OFFICE',awayEndsAt:form.enabled?form.awayEndsAt:null};await api.put(`/auto-replies/policies/${editing.value.accountId}`,payload);ElMessage.success('账号托管策略已保存');dialogOpen.value=false;await load()}catch(e){ElMessage.error(apiErrorMessage(e,'策略保存失败'))}finally{saving.value=false}}
function formatDate(v?:string){return v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function attemptType(s:AutoReplyAttemptStatus){return s==='SENT'?'success':s==='FAILED'?'danger':s==='SKIPPED'?'info':'warning'}
function quota(x:AutoReplyPolicy){return Math.min(100,Math.round(x.sentToday/Math.max(x.dailyLimit,1)*100))}
function deviceLabel(d?:BrowserDevice){return d?.runtimeState==='RUNNING'?'在线运行':d?.runtimeState==='PAUSED'?'已暂停':d?'离线':'未配对'}
async function setAway(x:AutoReplyPolicy,mode:'IN_OFFICE'|'TEMPORARY'|'AFTER_HOURS',hours=0){if(!x.configured){ElMessage.warning('请先由管理员配置该账号的托管策略');return}awayActionId.value=x.accountId;try{await ensureCsrf();await api.put(`/auto-replies/policies/${x.accountId}/away-mode`,{mode,endsAt:mode==='IN_OFFICE'?null:new Date(Date.now()+hours*3600000).toISOString()});ElMessage.success(mode==='IN_OFFICE'?'已结束托管，欢迎回来':'离开托管已开启');await load()}catch(e){ElMessage.error(apiErrorMessage(e,'托管状态更新失败'))}finally{awayActionId.value=''}}
async function createPairing(accountId:string){try{await ensureCsrf();const {data}=await api.post<{pairingToken:string}>('/browser-devices/pairings',{accountId});await ElMessageBox.alert(`配对令牌：${data.pairingToken}\n\n10 分钟内在 Chrome 扩展设置中输入。关闭后不再展示。`,'一次性浏览器配对令牌',{confirmButtonText:'我已安全保存'});await load()}catch(e){ElMessage.error(apiErrorMessage(e,'创建配对令牌失败'))}}
async function revokeDevice(d:BrowserDevice){try{await ElMessageBox.confirm(`撤销 ${d.displayName}？扩展将立即无法同步或发送。`,'撤销浏览器设备',{type:'warning'});await ensureCsrf();await api.delete(`/browser-devices/${d.id}`);ElMessage.success('设备已撤销');await load()}catch(e){if(e!=='cancel')ElMessage.error(apiErrorMessage(e,'撤销失败'))}}
onMounted(load)
</script>

<template><div class="page-shell auto-page">
  <header class="page-heading"><div><span class="eyebrow">AUTO REPLY</span><h1>回复设置与记录</h1><p>设置多久未回复后自动接待，以及查看每次发送结果。开启或结束托管请返回首页。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></header>
  <el-alert class="safety-alert" type="warning" :closable="false" show-icon title="托管回复只用于确认消息已收到，不代替 HR 做薪资、录用或面试承诺。遇到验证码、登录失效或页面变化时自动暂停。"/>
  <el-alert v-if="runtimeWarning" class="safety-alert" type="error" :closable="false" show-icon :title="runtimeWarning" description="请打开对应 Chrome Profile 和 BOSS 沟通页确认状态；未确认前保持停止。"/>
  <div v-if="loading" class="surface-panel"><el-skeleton :rows="8" animated/></div>
  <div v-else-if="errorMessage" class="surface-panel error-state"><el-icon><Warning/></el-icon><strong>自动跟进状态暂时无法加载</strong><span>{{errorMessage}}</span><el-button @click="load">重试</el-button></div>
  <template v-else>
    <nav class="module-nav"><button v-for="t in [{id:'accounts',name:'回复设置',desc:'超时时间与回复内容'},{id:'observations',name:'未读观察',desc:`${observations.length} 个只读会话`},{id:'attempts',name:'发送记录',desc:'成功、失败与跳过原因'}]" :key="t.id" :class="{active:activeTab===t.id}" @click="activeTab=t.id"><strong>{{t.name}}</strong><span>{{t.desc}}</span></button></nav>
    <section v-if="activeTab==='overview'" class="surface-panel quick-away"><div class="section-title-row"><div><h2>现在要离开吗？</h2><p>选择一个账号和离开时长，到期后服务端会自动停止托管。</p></div></div><div class="quick-away-list"><article v-for="x in policies" :key="x.accountId"><div><strong>{{x.accountName}}</strong><span v-if="x.awayActive">托管至 {{formatDate(x.awayEndsAt)}}</span><span v-else>当前在岗，不会自动接待</span></div><div><el-button v-if="x.awayActive" type="success" plain :loading="awayActionId===x.accountId" @click="setAway(x,'IN_OFFICE')">我已返回</el-button><template v-else><el-button :loading="awayActionId===x.accountId" @click="setAway(x,'TEMPORARY',1)">离开 1 小时</el-button><el-button type="primary" :loading="awayActionId===x.accountId" @click="setAway(x,'TEMPORARY',2)">离开 2 小时</el-button><el-button @click="setAway(x,'AFTER_HOURS',12)">下班托管</el-button></template></div></article></div></section>
    <template v-if="activeTab==='overview'">
      <div class="metrics"><article><span>自动运行账号</span><strong>{{stats.running}}<small> / {{stats.total}}</small></strong></article><article><span>需要关注</span><strong :class="{danger:stats.attention}">{{stats.attention}}</strong></article><article><span>今日已发送</span><strong>{{stats.sentToday}}</strong></article><article><span>在线浏览器</span><strong>{{stats.online}}</strong></article></div>
      <div class="overview-grid"><section class="surface-panel"><div class="section-title-row"><div><h2>账号运行状态</h2><p>先处理红色异常，再开启自动发送。</p></div><el-button text @click="activeTab='accounts'">管理策略</el-button></div><div v-if="!runtimeAccounts.length" class="empty">还没有可管理的招聘账号</div><article v-for="x in runtimeAccounts" :key="x.policy.accountId" class="health-row"><i>{{x.policy.accountName.slice(0,1)}}</i><div class="identity"><strong>{{x.policy.accountName}}</strong><span>{{x.policy.companyName}}</span></div><el-tag :type="runtimeMeta[x.state].type">{{runtimeMeta[x.state].label}}</el-tag><div class="quota"><span>今日额度 {{x.policy.sentToday}}/{{x.policy.dailyLimit}}</span><el-progress :percentage="quota(x.policy)" :show-text="false" :stroke-width="6"/></div><el-button v-if="canManage" text @click="openPolicy(x.policy)">配置</el-button></article></section>
      <aside class="surface-panel"><div class="section-title-row"><div><h2>需要处理</h2><p>{{attentionAccounts.length?'以下问题会阻止自动发送':'当前没有阻断项'}}</p></div></div><div v-if="!attentionAccounts.length" class="all-good"><b>✓</b><strong>链路状态正常</strong><small>仍会遵守限流与发送窗口</small></div><button v-for="x in attentionAccounts" :key="x.policy.accountId" class="attention" @click="activeTab=x.state==='OFFLINE'?'devices':'accounts'"><b></b><span><strong>{{x.policy.accountName}} · {{runtimeMeta[x.state].label}}</strong><small>{{x.device?.stopReason||'请检查账号能力、扩展登录和心跳状态'}}</small></span><em>处理 →</em></button></aside></div>
      <section class="surface-panel flow-panel"><div class="section-title-row"><div><h2>一次自动回复如何完成</h2><p>后端规则与发送租约是唯一权威，浏览器扩展只执行已授权任务。</p></div></div><div class="flow"><article v-for="(x,i) in [['识别新消息','只采集必要会话状态'],['校验超时与规则','人工已回复则立即跳过'],['签发单次发送租约','检查时段、间隔与额度'],['页面发送并回执','DOM 异常或验证码停机']]" :key="i"><b>{{i+1}}</b><div><strong>{{x[0]}}</strong><span>{{x[1]}}</span></div></article></div></section>
    </template>
    <section v-if="activeTab==='observations'" class="surface-panel"><div class="section-title-row"><div><h2>真实未读观察与安全草稿</h2><p>仅上传岗位名称和不可逆摘要；草稿经批准后可选择只填入当前输入框，系统绝不点击发送。</p></div><el-tag type="warning">草稿辅助</el-tag></div><el-empty v-if="!observations.length" :image-size="72" description="尚未收到浏览器未读快照"/><div v-else class="observation-list"><article v-for="x in observations" :key="x.id" :class="{expired:x.eligibilityStatus==='READY_FOR_REVIEW'}"><header><div class="identity"><strong>{{x.observedJobTitle||`匿名会话 ${x.anonymousKey}`}}</strong><span>{{x.accountName}} · {{x.companyName}} · {{x.observedJobTitle?`匿名会话 ${x.anonymousKey}`:'岗位未识别'}}</span></div><el-tag :type="x.eligibilityStatus==='READY_FOR_REVIEW'?'warning':x.eligibilityStatus==='APPROVED_DRAFT'?'success':'info'">{{eligibilityLabel[x.eligibilityStatus]}}</el-tag></header><div class="observation-metrics"><span><b>{{x.unreadCount}}</b> 条未读</span><span><b>{{duration(observationAge(x))}}</b> 持续未读</span><span><b>{{x.latestDirection==='INBOUND'?'候选人来信':x.latestDirection==='OUTBOUND'?'HR 已回复':'等待复核'}}</b> 最新方向</span></div><div v-if="x.draftContent" class="observation-draft"><div><el-tag size="small" :type="x.draftMode==='KNOWLEDGE'?'success':'warning'">{{x.draftMode==='KNOWLEDGE'?'已审核知识草稿':'通用回退草稿'}}</el-tag><small>{{x.draftReason}}</small></div><p>{{x.reviewedContent||x.draftContent}}</p><strong>{{x.fillStatus==='FILLED'?`已于 ${formatDate(x.filledAt)} 填入输入框，等待 HR 处理`:x.fillStatus==='UNKNOWN'?'填写结果不确定，已停止且不会重试':x.fillStatus==='READY'?'已批准，等待扩展只填写':'后台预备草稿 · 不会发送'}}</strong></div><div v-if="x.eligibilityStatus==='READY_FOR_REVIEW'" class="observation-actions"><el-button type="primary" @click="reviewObservation(x,'APPROVED')">审核草稿</el-button><el-button @click="reviewObservation(x,'HUMAN_TAKEOVER')">人工接管</el-button><el-button type="danger" plain @click="reviewObservation(x,'REJECTED')">拒绝</el-button></div><footer><span>详情复核 {{formatDate(x.detailVerifiedAt)}} · {{x.reviewNote||'无人工备注'}}</span><span>最近观测 {{formatDate(x.lastSeenAt)}}</span></footer></article></div></section>
    <section v-else-if="activeTab==='accounts'" class="surface-panel"><div class="section-title-row"><div><h2>每个账号怎么回复</h2><p>只需确认等待时间、可回复时段、每日上限和回复内容。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="runtimeMeta[runtimeState(x)].type">{{runtimeMeta[runtimeState(x)].label}}</el-tag></header><div class="mode"><strong>{{x.autoSendEnabled?'自动回复已允许':'发送前需审核'}}</strong><span>等待 {{x.responseTimeoutMinutes}} 分钟</span></div><el-alert v-if="activeDevice(x.accountId)&&deviceNeedsAttention(activeDevice(x.accountId)!)" type="error" :closable="false" :title="activeDevice(x.accountId)?.stopReason||'浏览器设备已离线'"/><dl><div><dt>可以回复的时间</dt><dd>{{x.sendingWindowStart.slice(0,5)}}–{{x.sendingWindowEnd.slice(0,5)}}</dd></div><div><dt>今天已回复</dt><dd>{{x.sentToday}} / {{x.dailyLimit}} 条</dd></div></dl><el-progress :percentage="quota(x)" :show-text="false"/><el-button v-if="canManage" :icon="Setting" :disabled="!x.messageSendCapable" @click="openPolicy(x)">修改回复设置</el-button><small v-else class="hint">如需修改，请联系招聘管理员。</small></article></div></section>
    <section v-else-if="activeTab==='devices'" class="surface-panel"><div class="section-title-row"><div><h2>浏览器伴随设备</h2><p>每个账号仅保留一台活跃设备；异常时必须人工介入。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="activeDevice(x.accountId)?.runtimeState==='RUNNING'?'success':'info'">{{deviceLabel(activeDevice(x.accountId))}}</el-tag></header><div v-if="activeDevice(x.accountId)" class="device"><Connection/><span><strong>{{activeDevice(x.accountId)?.displayName}}</strong><small>最后心跳 {{formatDate(activeDevice(x.accountId)?.lastHeartbeatAt)}}</small></span></div><div v-else class="unpaired">尚未配对 Chrome 扩展，无法检测消息或执行发送。</div><el-alert v-if="activeDevice(x.accountId)?.stopReason" type="warning" :closable="false" :title="activeDevice(x.accountId)?.stopReason"/><footer v-if="canManage"><el-button :icon="Connection" @click="createPairing(x.accountId)">{{activeDevice(x.accountId)?'重新配对':'生成配对令牌'}}</el-button><el-button v-if="activeDevice(x.accountId)" type="danger" plain :icon="Delete" @click="revokeDevice(activeDevice(x.accountId)!)">撤销</el-button></footer></article></div></section>
    <section v-else class="surface-panel"><div class="section-title-row attempts-head"><div><h2>发送记录</h2><p>查看每次发送租约结果，失败与跳过不计成功额度。</p></div><div class="filters"><el-select v-model="attemptAccountFilter" clearable placeholder="全部账号"><el-option v-for="x in policies" :key="x.accountId" :label="x.accountName" :value="x.accountId"/></el-select><el-select v-model="attemptStatusFilter" clearable placeholder="全部状态"><el-option v-for="(v,k) in statusLabels" :key="k" :label="v" :value="k"/></el-select></div></div><el-empty v-if="!filteredAttempts.length" :image-size="72" description="暂无符合条件的记录"/><div class="attempt-list"><article v-for="x in filteredAttempts" :key="x.id"><div class="identity"><strong>{{x.candidateName}}</strong><span>{{x.jobTitle}} · {{x.accountName}}</span></div><el-tag :type="attemptType(x.status)">{{statusLabels[x.status]}}</el-tag><div class="result"><strong>{{x.resultMessage||'等待处理结果'}}</strong><span>尝试 {{x.attemptCount}} 次 · {{formatDate(x.completedAt||x.createdAt)}}</span></div></article></div></section>
  </template>
  <el-dialog v-model="dialogOpen" :title="`${editing?.accountName??''} · 回复设置`" width="680px"><el-alert type="info" :closable="false" show-icon title="建议首次先人工审核，确认识别和回复都正常后再允许自动发送。"/><el-form label-position="top" class="policy-form"><div class="form-grid"><el-form-item label="启用未回复提醒"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="允许自动回复"><el-switch v-model="form.autoSendEnabled" :disabled="!form.enabled"/></el-form-item><el-form-item label="等待多少分钟"><el-input-number v-model="form.responseTimeoutMinutes" :min="5" :max="10080"/><small class="hint">HR 在这段时间内回复，系统就不会发送。</small></el-form-item><el-form-item label="每天最多回复"><el-input-number v-model="form.dailyLimit" :min="1" :max="200"/><small class="hint">达到上限后自动停止，第二天重新计算。</small></el-form-item><el-form-item label="开始时间"><el-time-picker v-model="form.sendingWindowStart" value-format="HH:mm:ss" format="HH:mm"/></el-form-item><el-form-item label="结束时间"><el-time-picker v-model="form.sendingWindowEnd" value-format="HH:mm:ss" format="HH:mm"/></el-form-item></div><el-form-item label="回复内容"><el-input v-model="form.replyTemplate" type="textarea" :rows="4" maxlength="1000" show-word-limit/><small class="hint">可以使用 {jobTitle} 自动带入职位名称。请只用于确认收到，不承诺薪资、录用或面试结果。</small></el-form-item></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存设置</el-button></template></el-dialog>
